    await this.prisma.$transaction(async (tx) => {
      await tx.$queryRaw`SELECT id FROM ws_newsletter_document WHERE id=${id}::uuid AND tenant_id=${ctx.tenantId}::uuid AND owner_id=${ctx.clerkUserId} FOR UPDATE`;
