          ],
        },
        data: { cancelledAt: new Date() },
      });
      await tx.wsNewsletterReviewer.deleteMany({
        where: { documentId: id, tenantId: ctx.tenantId, userId },
      });
    });
    return this.reviewers(ctx, id);
  }
